  const mime=file.type;const kind=mime.startsWith('image/')?'image':'audio';
  await action(async()=>{const encoded=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('File could not be read'));reader.readAsDataURL(file)});const r=await post('/conversations/'+activeId+'/media',{kind,mime_type:mime,content_base64:encoded});setAssistant(r.text);return r},'Analysis is a draft; check it before using. File contents were not saved.');
