  if(kind==='courier'){endpoint='/orders/'+modal.values.id+'/courier';}
  if(kind==='product'){endpoint=modal.values.id?'/products/'+modal.values.id:'/products';method=modal.values.id?'PUT':'POST';}
  if(kind==='order'){endpoint='/orders';try{data={...body,items:orderItems(form,products),request_id:modal.requestId};delete data.cart_product;delete data.cart_quantity;}catch(error){setError(error.message);return;}}
  if(kind==='media-checkout'){endpoint='/conversations/'+modal.values.conversation_id+'/attachments/'+modal.values.attachment_id+'/checkout-proposal';try{data={customer:body.customer,phone:body.phone,address:body.address,delivery_charge:body.delivery_charge,delivery_area:body.delivery_area||'',delivery_slot:body.delivery_slot||'',items:orderItems(form,products),request_id:modal.requestId}}catch(error){setError(error.message);return;}}
  if(kind==='lead'){endpoint='/leads';}
