  if(modal.kind==='conversation')return <>{input('customer','Customer name',{required:true,maxLength:120})}{select('channel','Channel',channels.filter(c=>c!=='All').map(c=><option key={c}>{c}</option>),'Website')}<p className="formnote">Creates a manual conversation, not a verified channel connection.</p></>;
