  if(['order','media-checkout'].includes(modal.kind))return <>{modal.kind==='media-checkout'?<p>These are untrusted media suggestions. Review every product and customer detail. This prepares a confirmation summary, not an order.</p>:customer}{input('customer','Customer name',{required:true,value:active?.customer})}<div className="formgrid">{input('phone','Phone number',{required:true,minLength:5,maxLength:40})}{modal.kind==='media-checkout'?<p>Cash on delivery (COD)</p>:select('payment_method','Payment method',['COD','bKash','Nagad','Bank'].map(x=><option key={x}>{x}</option>),'COD')}</div>{textarea('address','Full delivery address',{required:true,minLength:5,maxLength:2000})}<OrderLines products={products} initialItems={v.items}/><CheckoutDelivery api={api} initialFee={v.delivery_charge??((modal.kind==='media-checkout'?workspace.agent.delivery_outside:workspace.agent.delivery_inside)||0)} onError={setError}/>{modal.kind==='order'&&<>{v.reorder&&<><p className="notice left">Reorder draft only. {(v.changes||[]).join(' · ')}</p><label className="checkrow"><input type="checkbox" required/>Customer confirmed the current items, prices, contact details and delivery terms.</label></>}</>}<p className="formnote">Quoted prices and stock are rechecked together for every product before the order is saved. Payment is recorded as unverified; no courier is booked.</p></>;
  if(modal.kind==='lead')return <>{customer}{input('name','Name',{required:true,value:active?.customer})}{input('phone','Phone',{maxLength:40})}{textarea('interest','Interested in',{maxLength:2000})}<div className="formgrid">{select('stage','Pipeline stage',stages.map(x=><option key={x}>{x}</option>),'New')}{select('temperature','Lead temperature',['Hot','Warm','Cold'].map(x=><option key={x}>{x}</option>),'Warm')}</div>{input('next_contact','Next contact',{type:'datetime-local'})}</>;
  if(modal.kind==='booking')return <>{customer}{input('customer','Customer name',{required:true,value:active?.customer})}{input('service','Service / appointment',{required:true})}<div className="formgrid">{input('starts_at','Starts at (your local time)',{type:'datetime-local',required:true})}{input('duration_minutes','Duration (minutes)',{type:'number',min:15,max:1440,value:60,required:true})}</div>{input('resource','Staff / room / resource',{required:true,value:'Main'})}<div className="formgrid">{input('advance','Reported advance (BDT)',{type:'number',min:0,value:0})}{input('transaction_id','Reported transaction ID')}</div><p className="formnote">Advance payment is not verified. Confirmation creates reminder drafts, which are not automatically sent.</p></>;
